from tests.models import quote
from z3sol import ops
from z3sol.ir import UINT256, Call, Const, Function, If, Model, Return, Var
from z3sol.solidity import names, source

QUOTE = """\
// SPDX-License-Identifier: Apache-2.0
// Generated by z3sol from DepositSubsidy._quoteSubsidy. Do not edit.
pragma solidity >=0.8.27;

import {Math} from "@oz/utils/math/Math.sol";

library DepositSubsidyQuoteSubsidyModel {
  uint128 internal constant MAX_PRIORITY_FEE_WEI = 100000000;

  struct Inputs {
    uint256 _fee;
    uint256 _reimbursableGas;
    uint256 _tokenPerEth;
    uint128 targetRelayerProfit;
    uint128 maxSubsidyPerOperation;
    uint256 pot;
    uint256 txGasPrice;
    uint256 baseFee;
  }

  function _quoteSubsidy(Inputs memory i) internal pure returns (uint256) {
    if (i._reimbursableGas == 0) {
      return 0;
    }
    uint256 gasPrice = Math.min(i.txGasPrice, (i.baseFee + MAX_PRIORITY_FEE_WEI));
    uint256 gasCost = Math.mulDiv((i._reimbursableGas * gasPrice), i._tokenPerEth, 1e18);
    uint256 targetPayout = gasCost + Math.min(i.targetRelayerProfit, i._fee);
    if (targetPayout <= i._fee) {
      return 0;
    }
    uint256 subsidy = Math.min((targetPayout - i._fee), i.maxSubsidyPerOperation);
    return Math.min(subsidy, i.pot);
  }
}

contract DepositSubsidyQuoteSubsidyHost {
  function run(DepositSubsidyQuoteSubsidyModel.Inputs memory i) external pure returns (uint256) {
    return DepositSubsidyQuoteSubsidyModel._quoteSubsidy(i);
  }
}
"""


def test_the_quote_model_emits_the_contract_operators_in_source_order():
    assert source(quote()) == QUOTE


def test_a_callee_is_its_own_function_and_takes_the_inputs():
    x, a = Var("x"), Var("a", input=True)
    callee = Function("_g", (x,), UINT256, (If(ops.make("eq", x, Const(0)), (Return(Const(1)),), (Return(x),)),))
    model = Model(
        "C", Function("f", (a,), UINT256, (Return(Call("_g", (a,), UINT256)),)), callees=(callee,), pragma="0.8.30"
    )
    text = source(model)
    assert "    return _g(i, i.a);\n" in text
    assert "  function _g(Inputs memory i, uint256 x) internal pure returns (uint256) {\n" in text
    assert "    if (x == 0) {\n      return 1;\n    } else {\n      return x;\n    }\n" in text
    assert names(model) == ("CFModel", "CFHost")
